import { useState } from 'react'

export default function Counter() {
  const [count, setCount] = useState(0)

  return (
    <button onClick={() => setCount((current) => current + 1)}>
      Clicked {count} times
    </button>
  )
}

import { useState } from 'react'

export default function Preferences() {
  const [form, setForm] = useState({ email: '', newsletter: true })

  function handleChange(event) {
    const { name, type, value, checked } = event.target
    setForm((current) => ({
      ...current,
      [name]: type === 'checkbox' ? checked : value,
    }))
  }

  return (
    <form>
      <input name="email" value={form.email} onChange={handleChange} />
      <label>
        <input
          type="checkbox"
          name="newsletter"
          checked={form.newsletter}
          onChange={handleChange}
        />
        Send me the newsletter
      </label>
    </form>
  )
}

import { useEffect, useState } from 'react'

export default function Clock() {
  const [now, setNow] = useState(() => new Date())

  useEffect(() => {
    const id = setInterval(() => setNow(new Date()), 1000)
    return () => clearInterval(id)
  }, [])

  return <time dateTime={now.toISOString()}>{now.toLocaleTimeString()}</time>
}

import { useEffect, useState } from 'react'

export default function UserName({ id }) {
  const [name, setName] = useState('')

  useEffect(() => {
    const controller = new AbortController()

    fetch(`https://api.example.com/users/${id}`, { signal: controller.signal })
      .then((response) => response.json())
      .then((user) => setName(user.name))
      .catch((error) => {
        if (error.name !== 'AbortError') console.error(error)
      })

    return () => controller.abort()
  }, [id])

  return <p>{name}</p>
}

