export default function Inbox({ messages, query }) {
  const visible = messages.filter((message) =>
    message.subject.toLowerCase().includes(query.toLowerCase()),
  )

  if (visible.length === 0) {
    return <p>No messages match "{query}".</p>
  }

  return (
    <ul>
      {visible.map((message) => (
        <li key={message.id}>{message.subject}</li>
      ))}
    </ul>
  )
}

import { useState } from 'react'

export default function LoginForm({ onSubmit }) {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')

  function handleSubmit(event) {
    event.preventDefault()
    if (!email.includes('@')) {
      setError('Enter a valid email address.')
      return
    }
    setError('')
    onSubmit({ email, password })
  }

  return (
    <form onSubmit={handleSubmit} noValidate>
      <input
        type="email"
        value={email}
        onChange={(event) => setEmail(event.target.value)}
        placeholder="you@example.com"
      />
      <input
        type="password"
        value={password}
        onChange={(event) => setPassword(event.target.value)}
      />
      {error && <p role="alert">{error}</p>}
      <button type="submit" disabled={!email || !password}>
        Sign in
      </button>
    </form>
  )
}

import { useActionState } from 'react'

async function subscribe(previousState, formData) {
  const response = await fetch('https://api.example.com/subscribe', {
    method: 'POST',
    body: formData,
  })
  if (!response.ok) return { error: 'Subscription failed.' }
  return { message: 'Check your inbox to confirm.' }
}

export default function Newsletter() {
  const [state, formAction, pending] = useActionState(subscribe, {})

  return (
    <form action={formAction}>
      <input type="email" name="email" required />
      {state.error && <p role="alert">{state.error}</p>}
      {state.message && <p>{state.message}</p>}
      <button disabled={pending}>{pending ? 'Sending…' : 'Subscribe'}</button>
    </form>
  )
}

import { createContext, useContext, useState } from 'react'

const ThemeContext = createContext(null)

export function ThemeProvider({ children }) {
  const [theme, setTheme] = useState('light')
  const toggle = () => setTheme((current) => (current === 'light' ? 'dark' : 'light'))

  return (
    <ThemeContext.Provider value={{ theme, toggle }}>
      {children}
    </ThemeContext.Provider>
  )
}

export function useTheme() {
  const context = useContext(ThemeContext)
  if (context === null) {
    throw new Error('useTheme must be used inside ThemeProvider')
  }
  return context
}

import { useTheme } from './ThemeProvider'

export default function ThemeToggle() {
  const { theme, toggle } = useTheme()

  return (
    <button onClick={toggle}>
      Switch to {theme === 'light' ? 'dark' : 'light'} mode
    </button>
  )
}

